11	export const GET = async (
12	    request: NextRequest,
13	    props: { params: Promise<Record<string, string>> },
14	) => {
15	    const { purpose, token } = await props.params;
16	    const searchParams = request.nextUrl.searchParams;
17	    const redirectParam = searchParams.get('redirect') ?? '/';
18	    let redirect: URL;
19	
20	    try {
21	        let data = {};
22	
23	        switch (purpose) {
24	            case 'extra-email':
25	                data = await verifyEmail(token);
26	                break;
27	            case 'enquiry':
28	                data = await deliverContactEnquiry(token);
29	                break;
30	            default:
31	                throw new ValidationError(
32	                    `Invalid verification purpose "${purpose}". Must be one of: extra-email, enquiry.`,
33	                );
34	        }
35	
36	        redirect = buildURLWithParams(redirectParam, data);
37	    } catch (error) {
38	        captureUnexpectedError(error, {
39	            layer: 'route',
40	            action: 'verifyAuthToken',
41	            route: '/api/footy/auth/verify/[purpose]/[token]',
42	            tags: {
43	                purpose,
44	            },
45	            extra: {
46	                redirectParam,
47	            },
48	        });
49	        const { message: errorMessage } = toHttpErrorResponse(
50	            error,
51	            'Unable to verify email.',
52	        );
53	
54	        redirect = buildURLWithParams(redirectParam, { error: errorMessage });
55	    }
