10	/**
11	 * HTTP GET route handler that finalizes a player invitation claim using a token
12	 * route parameter and redirects the client to a specified URL.
13	 *
14	 * The handler:
15	 * - Resolves `token` from `props.params`.
16	 * - Reads the `redirect` query parameter from the incoming `request.nextUrl`
17	 *   (defaults to '/').
18	 * - Calls `finalizePlayerInvitationClaim(token)` to complete the claim.
19	 * - On success, redirects to the resolved redirect URL.
20	 * - On failure, redirects to the same URL with an `error` query parameter
21	 *   containing the error message.
22	 *
23	 * @param request - The incoming NextRequest (used to read search params like
24	 * `redirect`).
25	 * @param props - An object containing a `params` promise that resolves to route
26	 * params (expects `{ token }`).
27	 * @returns A NextResponse that performs a redirect to the target URL,
28	 * optionally including an `error` query param.
29	 */
30	export const GET = async (
31	    request: NextRequest,
32	    props: { params: Promise<Record<string, string>> },
33	) => {
34	    const { token } = await props.params;
35	    const searchParams = request.nextUrl.searchParams;
36	    const redirectParam = searchParams.get('redirect') ?? '/';
37	    let redirect: URL;
38	
39	    try {
40	        await finalizePlayerInvitationClaim(token);
41	
42	        redirect = buildURLWithParams(redirectParam, {});
43	    } catch (error) {
44	        captureUnexpectedError(error, {
45	            layer: 'route',
46	            action: 'finalizePlayerInvitationClaim',
47	            route: '/api/footy/auth/claim/[token]',
48	            extra: {
49	                redirectParam,
50	            },
51	        });
52	        const { message: errorMessage } = toHttpErrorResponse(
53	            error,
54	            'Unable to finalize invitation.',
55	        );
56	
57	        redirect = buildURLWithParams(redirectParam, { error: errorMessage });
58	    }
59	
60	    return NextResponse.redirect(redirect);
61	};
