1	import { NextResponse } from 'next/server';
2	
3	import { normalizeUnknownError, toHttpErrorResponse } from '@/lib/errors';
4	import { captureUnexpectedError } from '@/lib/observability/sentry';
5	
6	import { getPublicBaseUrl } from './urls';
7	
8	/**
9	 * Handles a GET request by invoking a service function and building a response.
10	 *
11	 * @template T - The type of the data returned by the service function.
12	 * @param serviceFunction - A function that processes the request parameters and returns a Promise
13	 *                          resolving to the data of type `T` or `null` if no data is found.
14	 * @param params - An object containing the request parameters as key-value pairs.
15	 * @param buildResponse - An optional function to build the response from the data. Defaults to `buildJsonResponse`.
16	 * @returns A Promise that resolves to a `NextResponse` object. If the service function returns `null`,
17	 *          a 404 response is returned. Otherwise, the response is built using the `buildResponse` function.
18	 */
19	export async function handleGET<T, S = T>(
20	    serviceFunction: ({
21	        params,
22	    }: {
23	        params: Record<string, string>;
24	    }) => Promise<T | null>,
25	    { params }: { params: Record<string, string> },
26	    hooks?: {
27	        sanitize?: (data: T) => Promise<S>;
28	        buildResponse?: (data: S) => Promise<NextResponse>;
29	    },
30	): Promise<NextResponse> {
31	    try {
32	        // If no sanitize hook provided, pass data through (cast via unknown to satisfy TS when S != T)
33	        const sanitize: (data: T) => Promise<S> =
34	            hooks?.sanitize ??
35	            (async (data: T) => await Promise.resolve(data as unknown as S));
36	        const buildResponse: (data: S) => Promise<NextResponse> =
37	            hooks?.buildResponse ?? buildJsonResponse;
38	
39	        const data = await serviceFunction({ params });
40	
41	        if (data == null) return new NextResponse('Not Found', { status: 404 });
42	
43	        const sanitizedData: S = await sanitize(data);
44	
45	        if (sanitizedData == null)
46	            return new NextResponse('Not Found', { status: 404 });
47	
48	        return buildResponse(sanitizedData);
49	    } catch (error) {
50	        const normalizedError = normalizeUnknownError(error);
51	        captureUnexpectedError(normalizedError, {
52	            layer: 'route',
53	            action: 'handleGET',
54	            extra: {
55	                params,
56	            },
57	        });
58	        const { status, message } = toHttpErrorResponse(normalizedError);
59	
60	        return new NextResponse(`Error: ${message}`, {
61	            status,
62	            headers: {
63	                'Content-Type': 'text/plain',
64	            },
65	        });
66	    }
67	}
68	
69	/**
70	 * Builds a JSON response with the provided data.
71	 *
72	 * @template T - The type of the data to include in the response.
73	 * @param data - The data to be serialized into JSON and included in the response body.
74	 * @returns A promise that resolves to a `NextResponse` object with the serialized JSON data,
75	 *          a status code of 200, and a `Content-Type` header set to `application/json`.
76	 */
77	async function buildJsonResponse<T>(data: T): Promise<NextResponse> {
78	    return Promise.resolve(
79	        NextResponse.json(data, {
80	            status: 200,
81	            headers: { 'Content-Type': 'application/json' },
82	        }),
83	    );
84	}
85	
86	/**
87	 * Builds a JSON error response for HTTP requests.
88	 *
89	 * Converts an error object into a standardized HTTP error response with
90	 * appropriate status code and JSON body containing the error message.
91	 *
92	 * @param error - The error object to convert. Can be any type.
93	 * @param fallbackMessage - The message to use if the error cannot be converted
94	 * to an HTTP response. Defaults to 'Internal Server Error'.
95	 * @returns A promise that resolves to a NextResponse with JSON-formatted error
96	 * details.
97	 */
98	export async function buildJsonErrorResponse(
99	    error: unknown,
100	    fallbackMessage = 'Internal Server Error',
101	): Promise<NextResponse> {
102	    const { status, message } = toHttpErrorResponse(error, fallbackMessage);
103	
104	    return Promise.resolve(
105	        NextResponse.json(
106	            { message },
107	            {
108	                status,
109	                headers: { 'Content-Type': 'application/json' },
110	            },
111	        ),
112	    );
113	}
114	
115	/**
116	 * Builds a PNG response with the provided data.
117	 *
118	 * @param data - The Buffer to be converted into a PNG response.
119	 * @returns A promise that resolves to a `NextResponse` object with the data
120	 *          as a PNG and the appropriate headers.
121	 */
122	export async function buildPngResponse(data: Buffer): Promise<NextResponse> {
123	    return Promise.resolve(
124	        new NextResponse(new Uint8Array(data), {
125	            status: 200,
126	            headers: { 'Content-Type': 'image/png' },
127	        }),
128	    );
129	}
130	
131	/**
132	 * Build a URL by resolving a base URI against the application's public base URL
133	 * and appending query parameters.
134	 *
135	 * To prevent open-redirect attacks, the resulting URL's origin must match the
136	 * application's public base URL. If the caller supplies an absolute URL whose
137	 * origin differs (e.g. `https://evil.com`), the path is discarded and the
138	 * application root (`/`) is used instead.
139	 *
140	 * @param baseUri - The base path or URL to resolve. Should be a relative path
141	 * (e.g. `/footy/response`). Absolute URLs pointing to a different origin are
142	 * treated as the root path.
143	 * @param params - An object whose keys and values will be appended as query
144	 * parameters. Multiple values for the same key will be appended (not replaced).
145	 * @returns A URL instance representing the resolved URL with the appended query
146	 * parameters.
147	 */
148	export function buildURLWithParams(
149	    baseUri: string,
150	    params: Record<string, string>,
151	) {
152	    const base = getPublicBaseUrl().toString();
153	    const url = new URL(baseUri, base);
154	    const expectedOrigin = new URL(base).origin;
155	
156	    // Prevent open redirects: if the resolved origin differs from our own,
157	    // fall back to the application root.
158	    if (url.origin !== expectedOrigin) {
159	        return buildURLWithParams('/', params);
160	    }
161	
162	    Object.entries(params).forEach(([key, value]) => {
163	        url.searchParams.append(key, value);
164	    });
165	
166	    return url;
167	}
