49	 * verification.
50	 * @param deps - Optional dependencies for email verification, contact enquiry,
51	 * and email sending services. Defaults to `defaultDeps`.
52	 *
53	 * @returns A promise that resolves when all operations are complete.
54	 */
55	export async function sendEnquiryCore(
56	    data: EnquiryInput,
57	    redirectUrl: string,
58	    deps: SendEnquiryDeps = defaultDeps,
59	) {
60	    const { token, expiresAt } = createVerificationToken();
61	
62	    await deps.emailVerificationService.create({
63	        email: data.email,
64	        token,
65	        expiresAt,
66	    });
67	
68	    await deps.contactEnquiryService.create({
69	        name: data.name,
70	        email: data.email,
71	        message: data.message,
72	        token,
73	    });
74	
75	    const verificationLink = new URL(
76	        `/api/footy/auth/verify/enquiry/${token}?redirect=${encodeURIComponent(redirectUrl)}`,
77	        getPublicBaseUrl(),
78	    ).toString();
79	
80	    const html = [
81	        `<p>Hello ${data.name},</p>`,
82	        '<p>Please confirm your enquiry by clicking the link below:</p>',
