95	/**
96	 * Delivers a contact enquiry by sending an email with the enquiry details and
97	 * marking the enquiry as delivered.
98	 *
99	 * @param token - The unique token identifying the contact enquiry.
100	 * @param deps - Optional dependencies required for delivering the enquiry.
101	 * Defaults to `defaultDeps`.
102	 * @returns An object indicating the result of the operation:
103	 *   - `{ enquiry: 'already-delivered' }` if the enquiry has already been
104	 *     delivered.
105	 *   - `{ enquiry: 'verified' }` if the enquiry was successfully delivered and
106	 *     verified.
107	 * @throws {NotFoundError} If the enquiry cannot be found for the provided token.
108	 */
109	export async function deliverContactEnquiryCore(
110	    token: string,
111	    deps: SendEnquiryDeps = defaultDeps,
112	) {
113	    const enquiry = await deps.contactEnquiryService.getByToken(token);
114	
115	    if (!enquiry) {
116	        throw new NotFoundError('Enquiry not found for this verification.');
117	    }
118	
119	    if (enquiry.deliveredAt) {
120	        return { enquiry: 'already-delivered' } as const;
121	    }
122	
123	    const formattedMessage = formatMessage(enquiry.message);
124	    const subject = `Enquiry from ${enquiry.name}`;
125	
126	    const html = [
127	        '<p>New enquiry received:</p>',
128	        `<p><strong>Name:</strong> ${enquiry.name}</p>`,
129	        `<p><strong>Email:</strong> <a href="mailto:${enquiry.email}">${enquiry.email}</a></p>`,
130	        `<p><strong>Message:</strong><br />${formattedMessage || '-'}</p>`,
131	    ].join('');
132	
133	    await deps.sendEmailCore({
134	        to: config.contactEmailDestination,
135	        subject,
136	        html,
137	    });
138	
139	    await deps.emailVerificationService.markUsed(token);
140	    await deps.contactEnquiryService.markDelivered(enquiry.id);
141	
142	    return { enquiry: 'verified' } as const;
143	}
