40	/**
41	 * Retrieves and validates an invitation by its token.
42	 *
43	 * @param token - The invitation token to validate.
44	 * @param deps - The dependencies providing access to invitation and player
45	 * email services.
46	 * @returns The valid invitation object associated with the provided token.
47	 * @throws If the token is missing, the invitation is not found, expired,
48	 * already used, lacks a player reference, or the email is already associated
49	 * with a different player.
50	 */
51	async function getValidInvitation(
52	    token: string,
53	    deps: ClaimPlayerInvitationDeps,
54	) {
55	    const now = new Date();
56	
57	    if (!token) {
58	        throw new ValidationError('Missing invitation token.', {
59	            publicMessage: 'This invitation link is invalid.',
60	        });
61	    }
62	
63	    const invitation = await deps.emailVerificationService.getByToken(token);
64	
65	    if (!invitation) {
66	        throw new NotFoundError('Invitation not found or expired.', {
67	            publicMessage: 'This invitation link is invalid or has expired.',
68	        });
69	    }
70	
71	    if (invitation.usedAt) {
72	        throw new ConflictError('Invitation has already been used.', {
73	            publicMessage: 'This invitation has already been used.',
74	        });
75	    }
76	    if (invitation.expiresAt <= now) {
77	        throw new ConflictError('Invitation has expired.', {
78	            publicMessage: 'This invitation has expired.',
79	        });
80	    }
81	
82	    if (!invitation.playerId) {
83	        throw new ValidationError('Invitation is missing a player reference.', {
84	            publicMessage: 'This invitation link is invalid.',
85	        });
86	    }
87	
88	    const existingExtraEmail = await deps.playerExtraEmailService.getByEmail(
89	        invitation.email,
90	    );
91	    if (
92	        existingExtraEmail &&
93	        existingExtraEmail.playerId !== invitation.playerId
94	    ) {
95	        throw new ConflictError(
96	            'Email address already belongs to another player.',
97	            {
98	                publicMessage:
99	                    'This email address is already associated with a different player.',
100	            },
101	        );
102	    }
103	
104	    return invitation;
105	}
