111	 * Validates the invitation token, ensures the invitation includes a `playerId`,
112	 * retrieves the corresponding player, and returns a summary payload containing
113	 * the player's name, the invitation email, and the original token.
114	 *
115	 * @param token - The invitation token to validate and claim.
116	 * @param deps - Optional dependencies required for validation and data
117	 * retrieval. Defaults to `defaultDeps`.
118	 * @returns An object containing:
119	 * - `name`: The player's display name.
120	 * - `email`: The email address associated with the invitation.
121	 * - `token`: The original invitation token passed in.
122	 *
123	 * @throws {Error} If no player exists for the given `playerId`.
124	 * @throws {Error} Propagates errors from invitation validation (e.g., invalid
125	 * or expired token).
126	 */
127	export async function claimPlayerInvitationCore(
128	    token: string,
129	    deps: ClaimPlayerInvitationDeps = defaultDeps,
130	) {
131	    const invitation = await getValidInvitation(token, deps);
132	
133	    const player = await deps.playerService.getById(invitation.playerId!);
134	
135	    if (!player) {
136	        throw new NotFoundError('Player not found.', {
137	            publicMessage: 'This invitation link is invalid.',
138	        });
139	    }
140	
141	    return {
142	        name: player.name,
143	        email: invitation.email,
144	        token,
145	    };
146	}
147	
148	/**
149	 * Finalizes the claim of a player invitation by linking the current user's
150	 * account to the player.
151	 *
152	 * This function performs the following operations:
153	 * 1. Validates the invitation token
154	 * 2. Verifies the session user exists and their email matches the invitation
155	 * 3. Ensures the user account is not already linked to a different player
156	 * 4. Links the current user to the player
157	 * 5. Updates the player with the account email
158	 * 6. Marks the invitation token as used
159	 * 7. Sends verification emails for any unverified extra emails associated with
160	 *    the player
161	 *
162	 * @param token - The invitation token to validate and process
163	 * @param deps - Optional dependencies object containing services for auth,
164	 * player management, email verification, and email sending. Uses default
165	 * dependencies if not provided.
166	 *
167	 * @throws {Error} If the invitation is invalid
168	 * @throws {Error} If no session user is found or the user email/ID is missing
169	 * @throws {Error} If the session user's email does not match the invitation
170	 * email
171	 * @throws {Error} If the session user account is already linked to a different
172	 * player
173	 *
174	 * @returns A promise that resolves when the invitation claim process is
175	 * complete
176	 */
177	export async function finalizePlayerInvitationClaimCore(
178	    token: string,
179	    deps: ClaimPlayerInvitationDeps = defaultDeps,
180	) {
181	    const invitation = await getValidInvitation(token, deps);
182	
183	    const sessionUser = await deps.authService.getSessionUser();
184	
185	    if (!sessionUser?.id || !sessionUser.email) {
186	        throw new AuthError('Login account not found for invitation.');
187	    }
188	
189	    if (sessionUser.email.toLowerCase() !== invitation.email.toLowerCase()) {
190	        throw new AuthError('Login account email does not match invitation.');
191	    }
192	
193	    if (sessionUser.playerId && sessionUser.playerId !== invitation.playerId) {
194	        throw new ConflictError(
195	            'Login account is already linked to another player.',
196	        );
197	    }
198	
199	    await deps.authService.updateCurrentUser({
200	        playerId: invitation.playerId!,
201	    });
202	    await deps.playerService.update({
203	        id: invitation.playerId!,
204	        accountEmail: invitation.email,
205	    });
206	    await deps.emailVerificationService.markUsed(token);
207	
208	    const extraEmails = await deps.playerExtraEmailService.getAll(
209	        invitation.playerId!,
210	    );
211	    const unverifiedExtraEmails = extraEmails.filter(
212	        (extraEmail) => !extraEmail.verifiedAt,
213	    );
214	    const player = await deps.playerService.getById(invitation.playerId!);
215	
216	    await Promise.all(
217	        unverifiedExtraEmails.map((extraEmail) =>
218	            deps.sendEmailVerification(extraEmail.email, player ?? undefined),
219	        ),
