35	/**
36	 * Handles the core logic for sending an enquiry and initiating email
37	 * verification.
38	 *
39	 * This function performs the following steps:
40	 * 1. Generates a verification token and expiration time.
41	 * 2. Stores the verification token associated with the user's email.
42	 * 3. Creates a contact enquiry record with the provided details and token.
43	 * 4. Constructs a verification link for the user to confirm their enquiry.
44	 * 5. Sends a verification email to the user with the confirmation link.
45	 *
46	 * @param data - The enquiry input containing the user's name, email, and
47	 * message.
48	 * @param deps - Optional dependencies for email verification, contact enquiry,
49	 * and email sending services. Defaults to `defaultDeps`.
50	 *
51	 * @returns A promise that resolves when all operations are complete.
52	 */
53	export async function sendEnquiryCore(
54	    data: EnquiryInput,
55	    deps: SendEnquiryDeps = defaultDeps,
56	) {
57	    const { token, expiresAt } = createVerificationToken();
58	
59	    await deps.emailVerificationService.create({
60	        email: data.email,
61	        token,
62	        expiresAt,
63	    });
64	
65	    await deps.contactEnquiryService.create({
66	        name: data.name,
67	        email: data.email,
68	        message: data.message,
69	        token,
70	    });
71	
72	    const verificationLink = new URL(
73	        `/footy/auth/verify/enquiry/${token}`,
74	        getPublicBaseUrl(),
75	    ).toString();
76	
77	    const html = [
78	        `<p>Hello ${data.name},</p>`,
79	        '<p>Please confirm your enquiry by clicking the link below:</p>',
80	        `<p><a href="${verificationLink}">Verify your email</a></p>`,
81	        '<p>We will send your message once this is confirmed.</p>',
82	        '<p>If you did not request this, you can ignore this message.</p>',
83	    ].join('');
84	
85	    await deps.sendEmailCore({
86	        to: data.email,
87	        subject: 'Confirm your enquiry',
88	        html,
89	    });
90	}
