19	export function GET(request: NextRequest): Response {
20	    const channel = request.nextUrl.searchParams.get(
21	        'channel',
22	    ) as FootyChannel | null;
23	
24	    if (!channel) {
25	        return new Response('Missing channel parameter', { status: 400 });
26	    }
