29	        start(controller) {
30	            const listener = () => {
31	                controller.enqueue(
32	                    encoder.encode('event: update\ndata: {}\n\n'),
33	                );
34	            };
35	
36	            emitter.on(channel, listener);
37	
38	            request.signal.addEventListener('abort', () => {
39	                emitter.off(channel, listener);
40	                controller.close();
41	            });
42	        },
43	    });
44	
45	    return new Response(stream, {
46	        headers: {
47	            'Content-Type': 'text/event-stream',
